                sh 'make cleanup'
            }
        }
    }
}
```

### 3. Conditional Execution
Use conditional statements to skip unnecessary steps based on certain conditions. This can save time and resources.

```groovy
pipeline {
    agent any
    stages {
        stage('Build') {
            steps {
                sh 'make build'
            }
        }
        stage('Test') {
            when {
                expression { return env.BRANCH_NAME == 'main' }
