    docker stats --no-stream --format "{{.Name}}\t{{.MemUsage}}" | grep -q "my-build-container" && echo "Memory Usage: $(docker stats --no-stream --format "{{.MemUsage}}" | grep "my-build-container")"
'''

// Run the monitor command every second
def monitorProcess = sh(script: "while true; do ${monitorCommand}; sleep 1; done &", returnStdout: true).trim()
