        String username = "your-username";
        String password = "your-password";

        // Create a Jira client
        JiraRestClientFactory factory = new AsynchronousJiraRestClientFactory();
        JiraRestClient client = factory.createWithBasicHttpAuthentication(jiraServerUri, username, password);

        // Create a new issue
        IssueInput issueInput = new IssueInputBuilder("BUG", "My Issue")
                .summary("This is my issue")
                .description("Detailed description of the issue")
                .priority(new PriorityInput("High"))
                .build();

        Promise<com.atlassian.jira.rest.client.api.domain.Issue> promise = client.getIssueClient().createIssue(issueInput);
        com.atlassian.jira.rest.client.api.domain.Issue createdIssue = promise.claim();

        System.out.println("Created issue: " + createdIssue.getKey());

        // Close the client
        client.close();
    }
}
