      target_port = 80
      protocol    = "TCP"
    }

    type = "LoadBalancer"  # Use LoadBalancer for cloud provider support
  }
}
```

### 3. Optimize Ingress Configuration

If you are using an Ingress controller, ensure it is configured to handle the increased load. You can also configure additional Ingress rules if needed.

```hcl
resource "kubernetes_ingress" "example" {
  metadata {
    name = "example-ingress"
  }

  spec {
