   - Confirm that the new secrets management practices are correctly implemented.

### Step 4: Migrate Existing Deployments

1. **Update Existing Deployments**:
   - Gradually update existing deployments with the new Terraform modules.
   - Use Terraform's state management to ensure a smooth transition.

2. **Monitor Changes**:
   - Closely monitor the deployment process to catch any issues early.
   - Use Terraform's `plan` command to preview changes before applying them.

### Example Implementation

Here's an example of how you might refactor and add new resources incrementally:

#### Refactor Variables and Providers

```hcl
variable "aws_access_key" {
  description = "AWS Access Key"
  type        = string
  sensitive   = true
}

variable "aws_secret_key" {
  description = "AWS Secret Key"
  type        = string
  sensitive   = true
}

provider "aws" {
  region     = "us-west-2"
  access_key = var.aws_access_key
  secret_key = var.aws_secret_key
}
```

#### Add Secrets Management Resources

```hcl
variable "enable_secrets_manager" {
  description = "Enable AWS Secrets Manager"
  type        = bool
  default     = false
}

resource "aws_secretsmanager_secret" "example" {
  count = var.enable_secrets_manager ? 1 : 0
  name  = "example-secret"
}

resource "aws_secretsmanager_secret_version" "example" {
  count     = var.enable_secrets_manager ? 1 : 0
  secret_id = aws_secretsmanager_secret.example[0].id
  secret_string = jsonencode({
    username = "example_user"
    password = "example_password"
  })
}
```

#### Restrict Access

```hcl
variable "enable_iam_policies" {
  description = "Enable IAM policies"
  type        = bool
  default     = false
}

resource "aws_iam_role" "example" {
  count = var.enable_iam_policies ? 1 :  0
  name  = "example-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "example" {
  count = var.enable_iam_policies ? 1 : 0
  role       = aws_iam_role.example[0].name
  policy_arn = "arn:aws:iam::aws:policy/SecretsManagerReadWrite"
}
```

#### Implement Rotation

```hcl
variable "enable_secret_rotation" {
  description = "Enable secret rotation"
  type        = bool
  default     = false
}

resource "aws_secretsmanager_secret_rotation" "example" {
  count = var.enable_secret_rotation ? 1 : 0
  secret_id         = aws_secretsmanager_secret.example[0].id
  rotation_lambda_arn = aws_lambda_function.rotation_lambda.arn
  rotation_rules {
    automatically_after_days = 90
  }
}

resource "aws_lambda_function" "rotation_lambda" {
  count = var.enable_secret_rotation ? 1 : 0
  filename      = "lambda_function_payload.zip"
  function_name = "example-rotation-lambda"
  role          = aws_iam_role.lambda_exec[0].arn
  handler       = "index.handler"
  source_code_hash = filebase64sha256("lambda_function_payload.zip")
  runtime       = "python3.8"
}

resource "aws_iam_role" "lambda_exec" {
  count = var.enable_secret_rotation ? 1 : 0
  name = "lambda-exec-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_exec_policy" {
  count = var.enable_secret_rotation ? 1 : 0
  role       = aws_iam_role.lambda_exec[0].name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}
```

#### Enable Logging

```hcl
variable "enable_cloudtrail" {
  description = "Enable CloudTrail"
  type        = bool
  default     = false
}

resource "aws_cloudtrail" "example" {
  count = var.enable_cloudtrail ? 1 : 0
  name               = "example-cloudtrail"
  s3_bucket_name     = "example-bucket"
  include_global_service_events = true
  is_multi_region_trail = true
  enable_logging = true
}

resource "aws_s3_bucket" "example" {
  count = var.enable_cloudtrail ? 1 : 0
  bucket = "example-bucket"
  acl    = "private"
}
```

### Conclusion

By following these steps, you can integrate new secrets management practices into your existing Terraform modules without disrupting current deployments. Start by refactoring variables and providers, then gradually add new resources and test them in a separate environment. Finally, migrate existing deployments with careful monitoring. If you have any specific questions or need further assistance, feel free to ask!

