Here's an example of how you can structure your pipeline to run stages in parallel and use caching:

```groovy
pipeline {
    agent none
    stages {
        stage('Build') {
            matrix {
                axes {
                    axis {
                        name 'ENV'
                        values 'dev', 'staging', 'prod'
                    }
                }
                stages {
                    stage('Checkout') {
                        agent { label 'build-agent' }
                        steps {
                            script {
                                checkout scm
                            }
                        }
                    }
                    stage('Build') {
                        agent { label 'build-agent' }
                        steps {
                            script {
                                cache(path: 'target', key: 'build-cache-${BUILD_ID}') {
                                    sh 'make build'
                                }
                            }
                        }
                    }
                }
            }
        }
        stage('Deploy') {
            parallel {
                stage('Deploy Dev') {
                    agent { label 'deploy-agent' }
                    steps {
                        script {
                            sh 'make deploy-dev'
                        }
                    }
                }
                stage('Deploy Staging') {
                    agent { label 'deploy-agent' }
                    steps {
                        script {
                            sh 'make deploy-staging'
                        }
                    }
                }
                stage('Deploy Prod') {
