                    def deploymentCoordinator = load("${WORKSPACE}/src/deployment_coordinator.py")

                    def now = new Date()
                    def tenMinutesLater = now + 10 * 60 * 1000
                    def twentyMinutesLater = now + 20 * 60 * 1000

                    deploymentCoordinator.schedule_deployment("Canary Deployment 1", "canary", tenMinutesLater)
                    deploymentCoordinator.schedule_deployment("Full Deployment 1", "full", now + 1 * 60 * 60 * 1000)
                    deploymentCoordinator.schedule_deployment("Canary Deployment 2", "canary", twentyMinutesLater)

