```python
import hashlib
import os

class SecurityAuditor:
    def __init__(self):
        self.audit_results = []

    def audit_deployment(self, deployment_name, deployment_files):
        """
        Perform a security audit on the deployment.

        :param deployment_name: Name of the deployment
        :param deployment_files: List of files to audit
        """
        audit_result = {
            'deployment_name': deployment_name,
            'files': [],
            'compliance': True,
            'errors': []
        }

        for file_path in deployment_files:
            if not os.path.isfile(file_path):
                audit_result['errors'].append(f"File {file_path} does not exist")
                continue

            try:
                with open(file_path, 'rb') as file:
                    file_content = file.read()
                    file_hash = hashlib.sha256(file_content).hexdigest()
                    audit_result['files'].append({
                        'file_path': file_path,
                        'file_hash': file_hash
                    })
            except Exception as e:
                audit_result['errors'].append(f"Failed to read file {file_path}: {str(e)}")
                audit_result['compliance'] = False

        self.audit_results.append(audit_result)

    def get_audit_results(self):
        """
        Get the audit results.

        :return: List of audit results
        """
        return self.audit_results

# Example usage:
security_auditor = SecurityAuditor()
deployment_files = [
    "/path/to/file1",
    "/path/to/file2",
    "/path/to/file3"
]
security_auditor.audit_deployment("Secure Deployment", deployment_files)
audit_results = security_auditor.get_audit_results()
print(audit_results)
```

