```python
import time

class RollbackStrategy:
    def __init__(self):
        self.rollback_plans = {}
        self.current_state = {}

    def create_rollback_plan(self, plan_name, deployment_state):
        """
        Create a rollback plan with the current state of the deployment.

        :param plan_name: Name of the rollback plan
        :param deployment_state: State of the deployment to be rolled back
        """
        self.rollback_plans[plan_name] = deployment_state
        self.current_state[plan_name] = deployment_state

    def execute_rollback_plan(self, plan_name):
        """
        Execute the rollback plan for the given plan name.

        :param plan_name: Name of the rollback plan to execute
        """
        if plan_name in self.rollback_plans:
            original_state = self.rollback_plans[plan_name]
            print(f"Executing rollback plan {plan_name} to restore state: {original_state}")

            # Simulate rollback process
            time.sleep(5)
            print(f"Rollback plan {plan_name} executed successfully")

            # Update current state to original state
            self.current_state[plan_name] = original_state
        else:
            print(f"No rollback plan found for {plan_name}")

    def get_current_state(self, plan_name):
        """
        Get the current state of the deployment for the given plan name.

        :param plan_name: Name of the rollback plan
        :return: Current state of the deployment
        """
        return self.current_state.get(plan_name, None)

