### Example Code

#### Load Balancing Script

First, let's define the load balancing script in Python:

```python
# load_balancer.py

from kubernetes import client, config
import random

# Load Kubernetes configuration
config.load_kube_config()

# Define a function to simulate pod startup
def startup_pod(node):
    # Simulate pod startup time
    time = random.uniform(0, 1)
    print(f"Pod started on {node} in {time:.2f} seconds")
    return time

# Define a function to perform load balancing
def load_balance(pods):
    v1 = client.CoreV1Api()

    # Get list of nodes
    nodes = v1.list_node().items
    node_names = [node.metadata.name for node in nodes]

    # Dictionary to keep track of pod counts on each node
    node_pod_counts = {node_name: _ for _, node_name in enumerate(node_names)}

    # Round-robin assignment
    for pod in pods:
        # Find the node with the least number of pods
        least_loaded_node = min(node_pod_counts, key=node_pod_counts.get)

        # Increment the count for the chosen node
        node_pod_counts[least_loaded_node] += 1

        # Assign pod to node
        print(f"Assigned pod {pod} to node {least_loaded_node}")

        # Simulate pod startup
        startup_pod(least_loaded_node)

# Test the functions
pods = [f"pod-{i}" for i in range(60)]
load_balance(pods)
```

